Here's a modern MSTest approach using `HttpMessageHandler` mocking, async test methods, and cancellation testing:

```csharp
[TestClass]
public class DataFetcherTests
{
    [TestMethod]
    [Timeout(5000)] // Fails if test hangs beyond 5s
    public async Task FetchAsync_ReturnsContent_WhenSuccessful()
    {
        // Arrange
        var handler = new FakeHandler("hello world", HttpStatusCode.OK);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        // Act
        var result = await fetcher.FetchAsync("https://example.com/data");

        // Assert
        Assert.AreEqual("hello world", result);
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_Throws_WhenStatusCodeIsError()
    {
        var handler = new FakeHandler("", HttpStatusCode.InternalServerError);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        await Assert.ThrowsExceptionAsync<HttpRequestException>(
            () => fetcher.FetchAsync("https://example.com/data"));
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_Throws_WhenCancelled()
    {
        var handler = new DelayHandler(TimeSpan.FromSeconds(30));
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);
        using var cts = new CancellationTokenSource();

        cts.Cancel(); // Cancel immediately

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com/data", cts.Token));
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_Throws_WhenCancelledDuringRequest()
    {
        var handler = new DelayHandler(TimeSpan.FromSeconds(30));
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);
        using var cts = new CancellationTokenSource(TimeSpan.FromMilliseconds(50));

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com/data", cts.Token));
    }

    // Lightweight fake handler — no mocking framework needed
    private sealed class FakeHandler(string content, HttpStatusCode status)
        : HttpMessageHandler
    {
        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            var response = new HttpResponseMessage(status)
            {
                Content = new StringContent(content)
            };
            return Task.FromResult(response);
        }
    }

    private sealed class DelayHandler(TimeSpan delay) : HttpMessageHandler
    {
        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            await Task.Delay(delay, cancellationToken);
            return new HttpResponseMessage(HttpStatusCode.OK);
        }
    }
}
```

**Key patterns used:**

| Pattern | Why |
|---------|-----|
| `async Task` test methods | MSTest natively awaits them — no `.Result` or `.GetAwaiter()` |
| `[Timeout(5000)]` | Prevents infinite hangs from deadlocked async code |
| `CancellationTokenSource` with timeout | Verifies cooperative cancellation mid-flight |
| Custom `HttpMessageHandler` | Avoids mocking frameworks; gives full control over HTTP behavior |
| `Assert.ThrowsExceptionAsync` | Proper async exception assertion (not `ThrowsException`) |

**Avoid these common mistakes:**
- Using `[Timeout]` with `Thread.Sleep`-based logic (it won't interrupt managed async code).
- Calling `.Result` or `.Wait()` on async methods in tests — this deadlocks on single-threaded contexts.
- Forgetting to pass `CancellationToken` through the call chain (your implementation already does this correctly).
